/// <summary>
/// PricingAttribute of table <c>MCRCustCategory</c> field Code.
/// </summary>
[UPSPricingMetadataDiscovery][UPSPricingAttributeSourceDiscovery(UPSPricingAttributeSource::Customer, UPSPricingAttributeSourceLevel::Header)]
internal class UPSPricingAttributeMCRCustCategoryCode extends UPSPricingAttributeMCRCustCategory implements UPSIPricingAttribute
{
}

Method.Source:
public str getName()
{
    return fieldPName(MCRCustCategory, Code);
}

public Set getAllowedValues()
{
    var             ret = new Set(Types::String);
    MCRCustCategory mCRCustCategory;

    while select mCRCustCategory
        group by Code
    {
        if (! ret.in(mCRCustCategory.Code))
        {
            ret.add(mCRCustCategory.Code);
        }
    }
    return ret;
}

protected void setQueryBuildDatasourceRange(QueryBuildDataSource _qbds, anytype _value)
{
    QueryBuildRange qbr;

    qbr = _qbds.addRange(fieldNum(MCRCustCategory, Code));
    qbr.value(queryValue(_value));
}
